.mobMn::before{content:'';position:absolute;top:100%;left:0;right:0;height:160px;background:inherit;pointer-events:none}
/* 4) Left-to-right pages only: nothing fixed may stick out past the right edge of the screen. In an LTR page the right side is scrollable, and phone browsers then widen the page and move fixed elements such as the bottom bar.
   The dark overlays (.fCls, .fxPu) were 200% wide (left/right -50%); they now stay inside the screen width (top/bottom -50% stays so they still cover the screen when the address bar hides) */
.fCls,.fxPu{left:0;right:0}
